from hypothesis import strategies as st


@st.composite
def gen(draw):
    kind = draw(st.integers(0, 3))
    if kind == 0:
        N = 1
    elif kind == 1:
        N = draw(st.integers(1, 10))
    else:
        N = draw(st.integers(1, 300))
    A = draw(st.integers(2, 6))
    X = draw(st.one_of(st.integers(1, 5), st.integers(1, 40), st.just(10**9)))
    Y = draw(st.one_of(st.integers(1, 5), st.integers(1, 40), st.just(10**9)))
    return f"{N} {A} {X} {Y}\n"


def validate(inp):
    t = inp.split()
    if len(t) != 4:
        return False
    try:
        N, A, X, Y = (int(x) for x in t)
    except ValueError:
        return False
    return (1 <= N <= 10**18 and 2 <= A <= 6
            and 1 <= X <= 10**9 and 1 <= Y <= 10**9)


def ref(inp):
    # State v = current value of N (always of the form floor(N/m)).
    # E(v) = minimal expected remaining cost from value v; E(0) = 0.
    # Operation 1: cost X, go to v//A, so candidate c = X + E(v//A).
    # Operation 2: cost Y, then with prob 1/6 each go to v//b for b=1..6.
    #   Let S = sum_{b=2..6} E(v//b). The b=1 outcome is a self-loop, so
    #   the die option is f(E) = Y + (S + E)/6 where E = E(v).
    # E = min(c, f(E)). Since f has slope 1/6 < 1, the fixed point gives
    #   E = min(c, (6Y + S)/5)
    # (if c <= (6Y+S)/5 then c <= f(c), so E = c; otherwise E = f(E) = (6Y+S)/5).
    # For v >= 1, every successor v//k is strictly smaller, so recursion terminates.
    N, A, X, Y = (int(x) for x in inp.split())
    memo = {0: 0.0}

    def E(v):
        if v in memo:
            return memo[v]
        c = X + E(v // A)
        S = sum(E(v // b) for b in range(2, 7))
        r = min(c, (6 * Y + S) / 5.0)
        memo[v] = r
        return r

    return f"{E(N):.15f}"


def same(inp, expected, got):
    try:
        e = float(expected.strip())
        g = float(got.strip())
    except ValueError:
        return False
    return abs(e - g) <= 1e-6 * max(1.0, abs(e))
