from fractions import Fraction
from hypothesis import strategies as st

@st.composite
def gen(draw):
    N = draw(st.one_of(
        st.integers(1, 3),
        st.integers(1, 60),
        st.sampled_from([1, 2, 5, 6, 7, 12, 36, 60]),
    ))
    A = draw(st.integers(2, 6))
    X = draw(st.one_of(st.integers(1, 5), st.integers(1, 40), st.sampled_from([1, 10**9 // 10**7])))
    Y = draw(st.one_of(st.integers(1, 5), st.integers(1, 40), st.sampled_from([1, 20])))
    return f"{N} {A} {X} {Y}\n"

def validate(inp):
    t = inp.split()
    if len(t) != 4:
        return False
    try:
        N, A, X, Y = (int(x) for x in t)
    except ValueError:
        return False
    return (1 <= N <= 10**18 and 2 <= A <= 6
            and 1 <= X <= 10**9 and 1 <= Y <= 10**9)

def ref(inp):
    # Exact DP over all values 0..N. f(n) = min over two policies:
    #  - pay X and divide by A:           X + f(n//A)
    #  - roll at n (outcome 1 returns to n, which again chooses optimally):
    #      f = Y + (f + S)/6, where S = sum_{b=2..6} f(n//b),
    #    so f = (6Y + S)/5.
    # Since f = min(c1, Y + (f+S)/6) has unique solution min(c1, (6Y+S)/5).
    N, A, X, Y = map(int, inp.split())
    f = [Fraction(0)] * (N + 1)
    for n in range(1, N + 1):
        c1 = X + f[n // A]
        S = sum(f[n // b] for b in range(2, 7))
        D = (Fraction(6 * Y) + S) / 5
        f[n] = min(c1, D)
    return f"{float(f[N]):.15f}"

def same(inp, expected, got):
    try:
        e = float(expected)
        g = float(got.strip())
    except ValueError:
        return False
    return abs(e - g) <= 1e-6 * max(1.0, abs(e))
